class Solution {
public:
    int minAnagramLength(string s) {
        int n = s.size();
        for (int k = 1; k <= n; ++k) {
            if (n % k != 0) continue;
            vector<int> base(26, 0);
            for (int i = 0; i < k; ++i) base[s[i] - 'a']++;
            bool valid = true;
            for (int start = k; start < n; start += k) {
                vector<int> cur(26, 0);
                for (int i = start; i < start + k; ++i) cur[s[i] - 'a']++;
                if (cur != base) {
                    valid = false;
                    break;
                }
            }
            if (valid) return k;
        }
        return n;
    }
};

class Solution {
    public int minAnagramLength(String s) {
        int n = s.length();
        for (int k = 1; k <= n; k++) {
            if (n % k != 0) continue;
            int[] base = new int[26];
            for (int i = 0; i < k; i++) base[s.charAt(i) - 'a']++;
            boolean valid = true;
            for (int start = k; start < n; start += k) {
                int[] cur = new int[26];
                for (int i = start; i < start + k; i++) cur[s.charAt(i) - 'a']++;
                if (!Arrays.equals(cur, base)) {
                    valid = false;
                    break;
                }
            }
            if (valid) return k;
        }
        return n;
    }
}

var minAnagramLength = function(s) {
    const n = s.length;
    for (let k = 1; k <= n; k++) {
        if (n % k !== 0) continue;
        const base = new Array(26).fill(0);
        for (let i = 0; i < k; i++) base[s.charCodeAt(i) - 97]++;
        let valid = true;
        for (let start = k; start < n; start += k) {
            const cur = new Array(26).fill(0);
            for (let i = start; i < start + k; i++) cur[s.charCodeAt(i) - 97]++;
            for (let c = 0; c < 26; c++) {
                if (cur[c] !== base[c]) {
                    valid = false;
                    break;
                }
            }
            if (!valid) break;
        }
        if (valid) return k;
    }
    return n;
};
